42	     * Returns the E.164 form of {@code raw}, or {@code null} when it cannot form a valid
43	     * E.164 number (including a {@code null} input).
44	     */
45	    static String toE164(String raw) {
46	        if (raw == null) {
47	            return null;
48	        }
49	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
50	        if (cleaned.isEmpty()) {
51	            return null;
52	        }
53	        String digits;
54	        if (cleaned.charAt(0) == '+') {
55	            digits = cleaned.substring(1);
56	        }
57	        else {
58	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
59	            digits = "61" + national;
60	        }
61	        if (digits.isEmpty() || !digits.chars().allMatch(c -> c >= '0' && c <= '9')) {
62	            return null;
63	        }
64	        if (digits.length() < 8 || digits.length() > 15) {
65	            return null;
66	        }
67	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTH.entrySet()) {
68	            String code = country.getKey();
69	            if (digits.startsWith(code)) {
70	                if (digits.length() - code.length() != country.getValue()) {
71	                    return null;
72	                }
73	                break;
74	            }
75	        }
76	        return "+" + digits;
